mapper.select:
select CUR_TABLE.* from ( SELECT SEM.emp_name,SEM.user_type,SEM.org_code,SEM.org_name,SEM.org_code_path, SEM.org_name_path,sop.EMPLOYEE_CODE AS emp_no,sepc1.car_infos, sepc1.lock_cars, sop.FACTORY_ID factory_code,sop.FACTORY_NAME,sop.update_time,sop.REMARK, CONVERT(DETAILS USING utf8) details_str FROM safety_park_employee_power_history sop LEFT JOIN safety.safety_employee_message sem ON sem.emp_no = sop.EMPLOYEE_CODE LEFT JOIN (SELECT employee_no, GROUP_CONCAT( sepc.car_no ) car_infos, GROUP_CONCAT( CASE WHEN lock_flag = '是' THEN car_no END ) lock_cars FROM safety.safety_employee_private_car sepc GROUP BY employee_no) sepc1 ON sop.EMPLOYEE_CODE = sepc1.employee_no WHERE 1 = 1
) CUR_TABLE where 1= 1
order by ${orderByClause}
limit ${offset}, ${limit}
limit ${limit}
